    ["Resource 1: Class Specific (Pips)"] = { "Resource 1: Class Specific (Pips)", "Recurso 1: específico de clase (puntos)", "Ressource 1: Klassenspezifisch (Punkte)", "Ressource 1 : spécifique à la classe (points)", "Risorsa 1: specifica della classe (punti)", "Recurso 1: específico da classe (pontos)", "Ресурс 1: классовый (ячейки)", "자원 1: 직업 전용 (칸)", "资源1：职业专属（格）", "資源1：職業專屬（格）" },
