    ["Restart Dungeon Run"] = { "Restart Dungeon Run", "Reiniciar recorrido de mazmorra", "Dungeondurchlauf neu starten", "Redémarrer le donjon", "Riavvia la spedizione", "Reiniciar masmorra", "Перезапустить прохождение", "던전 공략 다시 시작", "重新开始地下城", "重新開始地城" },
    ["Restore Cast Bar Defaults"] = { "Restore Cast Bar Defaults", "Restablecer barra de lanzamiento", "Zauberleiste zurücksetzen", "Rétablir la barre d'incantation par défaut", "Ripristina barra di lancio predefinita", "Restaurar padrões da barra de lançamento", "Сбросить полосу заклинаний", "시전바 기본값 복원", "恢复施法条默认设置", "還原施法條預設值" },
    ["Restore all Cooldown Manager settings to defaults?\n\nThis resets CDM Bars, Bar Glows, Buff Bars, and KUI Tracker, then reloads the UI."] = { "Restore all Cooldown Manager settings to defaults?\n\nThis resets CDM Bars, Bar Glows, Buff Bars, and KUI Tracker, then reloads the UI.", "¿Restablecer todos los ajustes del gestor de tiempos de reutilización a los valores predeterminados?\n\nEsto restablece las barras del CDM, los brillos de barra, las barras de beneficios y KUI Tracker, y luego recarga la interfaz.", "Alle Einstellungen des Abklingzeitenmanagers auf Standard zurücksetzen?\n\nDies setzt CDM-Leisten, Leistenleuchten, Stärkungszauberleisten und KUI Tracker zurück und lädt dann die Benutzeroberfläche neu.", "Rétablir tous les paramètres du gestionnaire de temps de recharge par défaut ?\n\nCela réinitialise les barres CDM, les surbrillances de barre, les barres d'améliorations et KUI Tracker, puis recharge l'interface.", "Ripristinare tutte le impostazioni del gestore dei tempi di recupero ai valori predefiniti?\n\nVerranno reimpostate le barre CDM, i bagliori delle barre, le barre dei benefici e KUI Tracker, poi l'interfaccia verrà ricaricata.", "Restaurar todas as configurações do gerenciador de recargas para o padrão?\n\nIsso redefine as barras do CDM, brilhos de barra, barras de bônus e o KUI Tracker, e depois recarrega a interface.", "Сбросить все настройки менеджера восстановления до стандартных?\n\nБудут сброшены полосы CDM, свечение полос, полосы эффектов и KUI Tracker, затем интерфейс перезагрузится.", "재사용 대기시간 관리자의 모든 설정을 기본값으로 되돌리시겠습니까?\n\nCDM 바, 바 반짝임, 강화 효과 바, KUI Tracker를 초기화한 뒤 UI를 다시 불러옵니다.", "将冷却管理器的所有设置恢复为默认值？\n\n这将重置CDM条、条发光、增益条和KUI Tracker，然后重载界面。", "將冷卻管理器的所有設定還原為預設值？\n\n這將重置CDM條、條發光、增益條與KUI Tracker，然後重新載入介面。" },
    ["Restore default Nameplates settings? This will reload the UI."] = { "Restore default Nameplates settings? This will reload the UI.", "¿Restablecer los ajustes predeterminados de las placas de nombre? Se recargará la interfaz.", "Standardeinstellungen der Namensplaketten wiederherstellen? Die Benutzeroberfläche wird neu geladen.", "Rétablir les paramètres par défaut des barres d'info ? L'interface sera rechargée.", "Ripristinare le impostazioni predefinite delle targhette? L'interfaccia verrà ricaricata.", "Restaurar as configurações padrão das placas de identificação? A interface será recarregada.", "Восстановить стандартные настройки индикаторов здоровья? Интерфейс будет перезагружен.", "이름표 설정을 기본값으로 되돌리시겠습니까? UI를 다시 불러옵니다.", "恢复姓名板默认设置？这将重载界面。", "還原名條預設設定？這將重新載入介面。" },
    ["Restored %d saved system settings."] = { "Restored %d saved system settings.", "Se restauraron %d ajustes guardados del sistema.", "%d gespeicherte Systemeinstellungen wiederhergestellt.", "%d paramètres système enregistrés restaurés.", "Ripristinate %d impostazioni di sistema salvate.", "%d configurações de sistema salvas restauradas.", "Восстановлено сохранённых системных настроек: %d.", "저장된 시스템 설정 %d개를 복원했습니다.", "已恢复%d项已保存的系统设置。", "已還原%d項已儲存的系統設定。" },
