    ["That string is a general or module profile. Use the profile importer."] = { "That string is a general or module profile. Use the profile importer.", "Esa cadena es un perfil general o de módulos. Usa el importador de perfiles.", "Diese Zeichenfolge ist ein allgemeines oder Modulprofil. Nutze den Profilimport.", "Cette chaîne est un profil général ou de modules. Utilisez l'importateur de profils.", "Questa stringa è un profilo generale o di moduli. Usa l'importatore di profili.", "Essa string é um perfil geral ou de módulos. Use o importador de perfis.", "Эта строка — общий профиль или профиль модулей. Используйте импорт профилей.", "이 문자열은 일반 또는 모듈 프로필입니다. 프로필 가져오기를 사용하세요.", "该字符串是通用或模块配置。请使用配置导入器。", "此字串是一般或模組設定檔。請使用設定檔匯入器。" },
    ["That string is a per-specialization CDM profile."] = { "That string is a per-specialization CDM profile.", "Esa cadena es un perfil del CDM por especialización.", "Diese Zeichenfolge ist ein CDM-Profil pro Spezialisierung.", "Cette chaîne est un profil CDM par spécialisation.", "Questa stringa è un profilo CDM per specializzazione.", "Essa string é um perfil do CDM por especialização.", "Эта строка — профиль CDM для специализации.", "이 문자열은 전문화별 CDM 프로필입니다.", "该字符串是按专精的 CDM 配置。", "此字串是按專精的 CDM 設定檔。" },
    ["That string is a per-specialization CDM profile. Use the CDM importer."] = { "That string is a per-specialization CDM profile. Use the CDM importer.", "Esa cadena es un perfil del CDM por especialización. Usa el importador del CDM.", "Diese Zeichenfolge ist ein CDM-Profil pro Spezialisierung. Nutze den CDM-Import.", "Cette chaîne est un profil CDM par spécialisation. Utilisez l'importateur CDM.", "Questa stringa è un profilo CDM per specializzazione. Usa l'importatore CDM.", "Essa string é um perfil do CDM por especialização. Use o importador do CDM.", "Эта строка — профиль CDM для специализации. Используйте импорт CDM.", "이 문자열은 전문화별 CDM 프로필입니다. CDM 가져오기를 사용하세요.", "该字符串是按专精的 CDM 配置。请使用 CDM 导入器。", "此字串是按專精的 CDM 設定檔。請使用 CDM 匯入器。" },
    ["The CDM profile was imported successfully."] = { "The CDM profile was imported successfully.", "El perfil del CDM se ha importado correctamente.", "Das CDM-Profil wurde erfolgreich importiert.", "Le profil CDM a été importé avec succès.", "Il profilo CDM è stato importato correttamente.", "O perfil do CDM foi importado com sucesso.", "Профиль CDM успешно импортирован.", "CDM 프로필을 가져왔습니다.", "CDM 配置已成功导入。", "CDM 設定檔已成功匯入。" },
    ["The flight time of this trip will not be recorded."] = { "The flight time of this trip will not be recorded.", "El tiempo de este vuelo no se guardará.", "Die Flugzeit dieser Reise wird nicht aufgezeichnet.", "La durée de ce vol ne sera pas enregistrée.", "Il tempo di questo volo non verrà registrato.", "O tempo deste voo não será registrado.", "Время этого полета не будет записано.", "이번 비행 시간은 기록되지 않습니다.", "本次飞行时间不会被记录。", "本次飛行時間不會被記錄。" },
    ["The gradient test needs a live frame with a real unit."] = { "The gradient test needs a live frame with a real unit.", "La prueba de degradado necesita un marco activo con una unidad real.", "Der Verlaufstest benötigt einen aktiven Rahmen mit einer echten Einheit.", "Le test de dégradé nécessite un cadre actif avec une unité réelle.", "Il test del gradiente richiede un riquadro attivo con un'unità reale.", "O teste de gradiente precisa de um quadro ativo com uma unidade real.", "Для проверки градиента нужна активная рамка с реальной единицей.", "그라데이션 테스트에는 실제 유닛이 있는 활성 프레임이 필요합니다.", "渐变测试需要一个带有真实单位的有效框体。", "漸層測試需要一個帶有真實單位的有效框架。" },
    ["The profile was imported successfully."] = { "The profile was imported successfully.", "El perfil se ha importado correctamente.", "Das Profil wurde erfolgreich importiert.", "Le profil a été importé avec succès.", "Il profilo è stato importato correttamente.", "O perfil foi importado com sucesso.", "Профиль успешно импортирован.", "프로필을 가져왔습니다.", "配置已成功导入。", "設定檔已成功匯入。" },
    ["The string contains no data for %s."] = { "The string contains no data for %s.", "La cadena no contiene datos para %s.", "Die Zeichenfolge enthält keine Daten für %s.", "La chaîne ne contient aucune donnée pour %s.", "La stringa non contiene dati per %s.", "A string não contém dados para %s.", "Строка не содержит данных для %s.", "문자열에 %s 데이터가 없습니다.", "该字符串不包含 %s 的数据。", "此字串不包含 %s 的資料。" },
    ["The string contains no module data."] = { "The string contains no module data.", "La cadena no contiene datos de módulos.", "Die Zeichenfolge enthält keine Moduldaten.", "La chaîne ne contient aucune donnée de module.", "La stringa non contiene dati dei moduli.", "A string não contém dados de módulos.", "Строка не содержит данных модулей.", "문자열에 모듈 데이터가 없습니다.", "该字符串不包含模块数据。", "此字串不包含模組資料。" },
    ["The string is empty."] = { "The string is empty.", "La cadena está vacía.", "Die Zeichenfolge ist leer.", "La chaîne est vide.", "La stringa è vuota.", "A string está vazia.", "Строка пуста.", "문자열이 비어 있습니다.", "字符串为空。", "字串為空。" },
    ["Then restart the game (or return to character select) and use /ktcpu reset."] = { "Then restart the game (or return to character select) and use /ktcpu reset.", "Luego reinicia el juego (o vuelve a la selección de personaje) y usa /ktcpu reset.", "Starte dann das Spiel neu (oder kehre zur Charakterauswahl zurück) und nutze /ktcpu reset.", "Redémarrez ensuite le jeu (ou revenez à la sélection du personnage) et utilisez /ktcpu reset.", "Poi riavvia il gioco (o torna alla selezione del personaggio) e usa /ktcpu reset.", "Depois reinicie o jogo (ou volte à seleção de personagem) e use /ktcpu reset.", "Затем перезапустите игру (или вернитесь к выбору персонажа) и используйте /ktcpu reset.", "그런 다음 게임을 재시작하거나 캐릭터 선택 화면으로 돌아간 뒤 /ktcpu reset 을 사용하세요.", "然后重启游戏（或返回角色选择界面）并使用 /ktcpu reset。", "然後重新啟動遊戲（或返回角色選擇畫面）並使用 /ktcpu reset。" },
    ["These colors apply when Color Source is set to Power Type."] = { "These colors apply when Color Source is set to Power Type.", "Estos colores se aplican cuando Origen del color está configurado como Tipo de recurso.", "Diese Farben gelten, wenn die Farbquelle auf Ressourcentyp gesetzt ist.", "Ces couleurs s'appliquent lorsque la source de couleur est réglée sur Type de ressource.", "Questi colori si applicano quando Fonte colore è impostata su Tipo di risorsa.", "Estas cores se aplicam quando a Fonte da cor está definida como Tipo de recurso.", "Эти цвета применяются, если источник цвета — «Тип ресурса».", "색상 출처가 자원 유형으로 설정된 경우 이 색상이 적용됩니다.", "当颜色来源设为能量类型时应用这些颜色。", "當顏色來源設為能量類型時套用這些顏色。" },
    ["Third Boss"] = { "Third Boss", "Tercer jefe", "Dritter Boss", "Troisième boss", "Terzo boss", "Terceiro chefe", "Третий босс", "세 번째 우두머리", "第三个首领", "第三個首領" },
    ["This addon makes the Blizzard windows movable."] = { "This addon makes the Blizzard windows movable.", "Este addon permite mover las ventanas de Blizzard.", "Dieses Addon macht die Blizzard-Fenster verschiebbar.", "Cet addon permet de déplacer les fenêtres de Blizzard.", "Questo addon rende spostabili le finestre di Blizzard.", "Este addon permite mover as janelas da Blizzard.", "Этот аддон позволяет перемещать окна Blizzard.", "이 애드온은 블리자드 창을 이동할 수 있게 합니다.", "此插件使暴雪窗口可以移动。", "此插件讓暴雪視窗可以移動。" },
    ["This continent"] = { "This continent", "Este continente", "Dieser Kontinent", "Ce continent", "Questo continente", "Este continente", "Этот континент", "이 대륙", "本大陆", "本大陸" },
    ["This element's size is set by its own module."] = { "This element's size is set by its own module.", "El tamaño de este elemento lo define su propio módulo.", "Die Größe dieses Elements wird von seinem eigenen Modul festgelegt.", "La taille de cet élément est définie par son propre module.", "La dimensione di questo elemento è impostata dal suo modulo.", "O tamanho deste elemento é definido pelo próprio módulo.", "Размер этого элемента задаётся его собственным модулем.", "이 요소의 크기는 해당 모듈에서 설정합니다.", "此元素的尺寸由其所属模块设置。", "此元素的尺寸由其所屬模組設定。" },
    ["This guided setup is for KullThranUI Forever, an adaptation of the Retail KullThranUI addon. It will help you choose language, fonts, visual style, and recommended addons."] = { "This guided setup is for KullThranUI Forever, an adaptation of the Retail KullThranUI addon. It will help you choose language, fonts, visual style, and recommended addons.", "Esta configuración guiada es para KullThranUI Forever, una adaptación del addon KullThranUI de Retail. Te ayudará a elegir idioma, fuentes, estilo visual y addons recomendados.", "Diese geführte Einrichtung ist für KullThranUI Forever, eine Anpassung des Retail-Addons KullThranUI. Sie hilft dir bei der Wahl von Sprache, Schriftarten, visuellem Stil und empfohlenen Addons.", "Cette configuration guidée est destinée à KullThranUI Forever, une adaptation de l'addon KullThranUI pour Retail. Elle vous aidera à choisir la langue, les polices, le style visuel et les addons recommandés.", "Questa configurazione guidata è per KullThranUI Forever, un adattamento dell'addon KullThranUI per Retail. Ti aiuterà a scegliere lingua, caratteri, stile visivo e addon consigliati.", "Esta configuração guiada é para o KullThranUI Forever, uma adaptação do addon KullThranUI do Retail. Ela ajudará você a escolher idioma, fontes, estilo visual e addons recomendados.", "Это пошаговая настройка для KullThranUI Forever — адаптации аддона KullThranUI для основной версии. Она поможет выбрать язык, шрифты, визуальный стиль и рекомендуемые аддоны.", "이 안내 설정은 본섭용 KullThranUI 애드온을 이식한 KullThranUI Forever용입니다. 언어, 글꼴, 시각 스타일, 추천 애드온을 선택하도록 도와줍니다.", "此引导设置适用于KullThranUI Forever，它是正式服KullThranUI插件的移植版本。它将帮助你选择语言、字体、视觉风格和推荐插件。", "此引導設定適用於KullThranUI Forever，它是正式版KullThranUI插件的移植版本。它將協助你選擇語言、字型、視覺風格與推薦插件。" },
    ["This importer only accepts module profiles, not full profiles."] = { "This importer only accepts module profiles, not full profiles.", "Este importador solo acepta perfiles de módulos, no perfiles completos.", "Dieser Import akzeptiert nur Modulprofile, keine vollständigen Profile.", "Cet importateur n'accepte que les profils de modules, pas les profils complets.", "Questo importatore accetta solo profili di moduli, non profili completi.", "Este importador só aceita perfis de módulos, não perfis completos.", "Этот импорт принимает только профили модулей, а не полные профили.", "이 가져오기는 모듈 프로필만 받으며 전체 프로필은 받지 않습니다.", "此导入器只接受模块配置，不接受完整配置。", "此匯入器只接受模組設定檔，不接受完整設定檔。" },
    ["This module auto-anchors above the top cooldown/resource stack. With Auto Width enabled, the width slider becomes a fallback value instead of the live width."] = { "This module auto-anchors above the top cooldown/resource stack. With Auto Width enabled, the width slider becomes a fallback value instead of the live width.", "Este módulo se ancla automáticamente encima del bloque superior de tiempos de reutilización o recursos. Con Anchura automática activada, el deslizador de anchura actúa como valor de respaldo en lugar de la anchura real.", "Dieses Modul verankert sich automatisch über dem obersten Abklingzeit-/Ressourcenstapel. Mit aktivierter automatischer Breite dient der Breitenregler nur als Ersatzwert statt als tatsächliche Breite.", "Ce module s'ancre automatiquement au-dessus de la pile supérieure de temps de recharge/ressources. Avec la largeur automatique activée, le curseur de largeur devient une valeur de secours au lieu de la largeur réelle.", "Questo modulo si ancora automaticamente sopra la pila superiore di tempi di recupero/risorse. Con Larghezza automatica attiva, il cursore della larghezza diventa un valore di riserva invece della larghezza effettiva.", "Este módulo se ancora automaticamente acima da pilha superior de recargas/recursos. Com a Largura automática ativada, o controle de largura passa a ser um valor reserva em vez da largura real.", "Этот модуль автоматически крепится над верхним блоком восстановления/ресурсов. При включённой автоширине ползунок ширины становится запасным значением, а не фактической шириной.", "이 모듈은 상단 재사용 대기시간/자원 묶음 위에 자동으로 고정됩니다. 자동 너비를 켜면 너비 슬라이더는 실제 너비 대신 대체 값으로 사용됩니다.", "此模块会自动锚定在顶部冷却/资源堆叠上方。启用自动宽度后，宽度滑块将作为备用值而非实际宽度。", "此模組會自動錨定在頂部冷卻/資源堆疊上方。啟用自動寬度後，寬度滑桿將作為備用值而非實際寬度。" },
    ["This option requires a text to be assigned"] = { "This option requires a text to be assigned", "Esta opción requiere asignar un texto", "Für diese Option muss ein Text zugewiesen sein", "Cette option nécessite qu'un texte soit assigné", "Questa opzione richiede l'assegnazione di un testo", "Esta opção requer que um texto seja atribuído", "Для этого параметра нужно назначить текст", "이 옵션을 사용하려면 텍스트를 지정해야 합니다", "此选项需要先分配文本", "此選項需要先指定文字" },
    ["This overwrites the active KullThranUI profile."] = { "This overwrites the active KullThranUI profile.", "Esto sobrescribe el perfil activo de KullThranUI.", "Dies überschreibt das aktive KullThranUI-Profil.", "Cela écrase le profil KullThranUI actif.", "Questo sovrascrive il profilo KullThranUI attivo.", "Isso substitui o perfil ativo do KullThranUI.", "Это перезапишет активный профиль KullThranUI.", "활성 KullThranUI 프로필을 덮어씁니다.", "这将覆盖当前的KullThranUI配置文件。", "這將覆寫目前的KullThranUI設定檔。" },
    ["This page has no registered module profile."] = { "This page has no registered module profile.", "Esta página no tiene un perfil de módulo registrado.", "Diese Seite hat kein registriertes Modulprofil.", "Cette page n'a aucun profil de module enregistré.", "Questa pagina non ha un profilo di modulo registrato.", "Esta página não tem um perfil de módulo registrado.", "У этой страницы нет зарегистрированного профиля модуля.", "이 페이지에는 등록된 모듈 프로필이 없습니다.", "此页面没有已注册的模块配置。", "此頁面沒有已註冊的模組設定檔。" },
    ["This session"] = { "This session", "Esta sesión", "Diese Sitzung", "Cette session", "Questa sessione", "Esta sessão", "Эта сессия", "이번 세션", "本次会话", "本次工作階段" },
    ["This session  •  Positions last until /reload."] = { "This session  •  Positions last until /reload.", "Esta sesión  •  Las posiciones duran hasta /reload.", "Diese Sitzung  •  Positionen bleiben bis zum /reload.", "Cette session  •  Les positions durent jusqu'au /reload.", "Questa sessione  •  Le posizioni durano fino al /reload.", "Esta sessão  •  As posições duram até o /reload.", "Эта сессия  •  Позиции сохраняются до /reload.", "이번 세션  •  /reload 전까지 위치가 유지됩니다.", "本次会话  •  位置保留到/reload为止。", "本次工作階段  •  位置保留到/reload為止。" },
    ["This session  •  Scale lasts until /reload."] = { "This session  •  Scale lasts until /reload.", "Esta sesión  •  La escala dura hasta /reload.", "Diese Sitzung  •  Die Skalierung bleibt bis zum /reload.", "Cette session  •  L'échelle dure jusqu'au /reload.", "Questa sessione  •  La scala dura fino al /reload.", "Esta sessão  •  A escala dura até o /reload.", "Эта сессия  •  Масштаб сохраняется до /reload.", "이번 세션  •  /reload 전까지 크기 비율이 유지됩니다.", "本次会话  •  缩放保留到/reload为止。", "本次工作階段  •  縮放保留到/reload為止。" },
    ["This will display ALL of your debuffs on enemy nameplates, rather than only the important ones."] = { "This will display ALL of your debuffs on enemy nameplates, rather than only the important ones.", "Muestra TODOS tus perjuicios en las placas de nombre enemigas, no solo los importantes.", "Zeigt ALLE deine Schwächungseffekte auf gegnerischen Namensplaketten an, nicht nur die wichtigen.", "Affiche TOUS vos affaiblissements sur les barres de nom ennemies, et pas seulement les plus importants.", "Mostra TUTTE le tue penalità sulle barre dei nomi nemiche, non solo quelle importanti.", "Exibe TODAS as suas penalidades nas placas de identificação inimigas, não apenas as importantes.", "Показывает ВСЕ ваши отрицательные эффекты на индикаторах противников, а не только важные.", "중요한 효과만이 아니라 내 모든 약화 효과를 적 이름표에 표시합니다.", "在敌方姓名板上显示你施加的所有减益效果，而不仅是重要的。", "在敵方名條上顯示你施加的所有減益效果，而不僅是重要的。" },
    ["Tick phases:"] = { "Tick phases:", "Fases del ciclo:", "Tick-Phasen:", "Phases du tick :", "Fasi del tick:", "Fases do ciclo:", "Фазы тика:", "틱 단계:", "刷新阶段：", "刷新階段：" },
    ["Time "] = { "Time ", "Tiempo ", "Zeit ", "Temps ", "Tempo ", "Tempo ", "Время ", "시간 ", "时间 ", "時間 " },
