    ["Use /ktcdmstats to see anchorTo/sizes/icons"] = { "Use /ktcdmstats to see anchorTo/sizes/icons", "Usa /ktcdmstats para ver anchorTo/tamaños/iconos", "Nutze /ktcdmstats für anchorTo/Größen/Symbole", "Utilisez /ktcdmstats pour voir anchorTo/tailles/icônes", "Usa /ktcdmstats per vedere anchorTo/dimensioni/icone", "Use /ktcdmstats para ver anchorTo/tamanhos/ícones", "Используйте /ktcdmstats, чтобы увидеть anchorTo/размеры/значки", "/ktcdmstats 로 anchorTo/크기/아이콘을 확인하세요", "使用 /ktcdmstats 查看 anchorTo/尺寸/图标", "使用 /ktcdmstats 查看 anchorTo/尺寸/圖示" },
    ["Use /ktdebug full to scan addons, modules, APIs and recent errors."] = { "Use /ktdebug full to scan addons, modules, APIs and recent errors.", "Usa /ktdebug full para analizar addons, módulos, APIs y errores recientes.", "Nutze /ktdebug full, um Addons, Module, APIs und aktuelle Fehler zu prüfen.", "Utilisez /ktdebug full pour analyser les addons, modules, API et erreurs récentes.", "Usa /ktdebug full per analizzare addon, moduli, API ed errori recenti.", "Use /ktdebug full para verificar addons, módulos, APIs e erros recentes.", "Используйте /ktdebug full, чтобы проверить аддоны, модули, API и недавние ошибки.", "/ktdebug full 로 애드온, 모듈, API, 최근 오류를 검사하세요.", "使用 /ktdebug full 扫描插件、模块、API 和最近的错误。", "使用 /ktdebug full 掃描插件、模組、API 和最近的錯誤。" },
